WITH c AS(SELECT user_id,reaction,COUNT(*) cnt FROM reactions GROUP BY user_id,reaction),t AS(SELECT user_id,COUNT(*) tot FROM reactions GROUP BY user_id HAVING COUNT(*)>=5) SELECT c.user_id,reaction dominant_reaction,ROUND(cnt/tot,2) reaction_ratio FROM c JOIN t USING(user_id) WHERE cnt=(SELECT MAX(cnt) FROM c x WHERE x.user_id=c.user_id) AND cnt/tot>=0.6 ORDER BY reaction_ratio DESC,user_id;